"""tool.py - Automated web page change detector with Discord webhook alerts.

Monitors a permitted web page or endpoint, compares content against a local
hash cache, and alerts a Discord channel when changes are detected.
"""

import argparse
import hashlib
import logging
import os
import sys
import requests

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
    datefmt="%Y-%m-%d %H:%M:%S",
)


def fetch_page(url: str, user_agent: str, timeout: int) -> str:
    headers = {"User-Agent": user_agent}
    try:
        response = requests.get(url, headers=headers, timeout=timeout)
        response.raise_for_status()
        return response.text
    except requests.RequestException as exc:
        logging.error("Failed to fetch %s: %s", url, exc)
        raise


def load_cached_hash(cache_path: str) -> str:
    if os.path.exists(cache_path):
        try:
            with open(cache_path, "r", encoding="utf-8") as handle:
                return handle.read().strip()
        except OSError as exc:
            logging.warning("Could not read cache file %s: %s", cache_path, exc)
    return ""


def save_cached_hash(cache_path: str, content_hash: str) -> None:
    try:
        with open(cache_path, "w", encoding="utf-8") as handle:
            handle.write(content_hash)
    except OSError as exc:
        logging.error("Failed to write cache file %s: %s", cache_path, exc)


def send_discord_alert(webhook_url: str, message: str, timeout: int) -> bool:
    payload = {"content": message}
    try:
        response = requests.post(webhook_url, json=payload, timeout=timeout)
        response.raise_for_status()
        logging.info("Discord alert posted successfully.")
        return True
    except requests.RequestException as exc:
        logging.error("Failed to post alert to Discord: %s", exc)
        return False


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Monitor permitted web pages and send Discord alerts on change."
    )
    parser.add_argument("--url", required=True, help="URL to monitor")
    parser.add_argument(
        "--webhook-url",
        default=os.environ.get("DISCORD_WEBHOOK_URL"),
        help="Discord incoming webhook URL (or set DISCORD_WEBHOOK_URL env var)",
    )
    parser.add_argument(
        "--cache-file",
        default=".page_hash.txt",
        help="Path to hash cache file (default: .page_hash.txt)",
    )
    parser.add_argument(
        "--user-agent",
        default="CodeToCapital-Monitor/1.0",
        help="Custom User-Agent header string",
    )
    parser.add_argument(
        "--timeout",
        type=int,
        default=15,
        help="Request timeout in seconds (default: 15)",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Check page and report status without sending Discord webhook",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()

    if not args.dry_run and not args.webhook_url:
        logging.error("Missing Discord webhook URL. Provide --webhook-url or set DISCORD_WEBHOOK_URL.")
        return 1

    logging.info("Checking %s ...", args.url)
    try:
        html_content = fetch_page(args.url, args.user_agent, args.timeout)
    except Exception:
        return 2

    current_hash = hashlib.sha256(html_content.encode("utf-8")).hexdigest()
    previous_hash = load_cached_hash(args.cache_file)

    if not previous_hash:
        logging.info("No baseline cache found. Saving initial snapshot.")
        save_cached_hash(args.cache_file, current_hash)
        if not args.dry_run:
            msg = f":information_source: Monitoring started for: {args.url}"
            send_discord_alert(args.webhook_url, msg, args.timeout)
        return 0

    if current_hash != previous_hash:
        logging.info("Page change detected! Old: %s..., New: %s...", previous_hash[:8], current_hash[:8])
        if args.dry_run:
            logging.info("[DRY RUN] Would send alert to Discord for: %s", args.url)
        else:
            msg = f":bell: **Change Detected!** Page updated: {args.url}"
            if send_discord_alert(args.webhook_url, msg, args.timeout):
                save_cached_hash(args.cache_file, current_hash)
    else:
        logging.info("No change detected on %s.", args.url)

    return 0


if __name__ == "__main__":
    sys.exit(main())
